#inScopeGatekeepers(role: CollaboratorRole): GatekeeperRecord[] {
  let boundIds: Set<WorkpieceId> | undefined;
  if (role === "use") {
    boundIds = new Set();
    for (let gadget of this.storage.gadgets.list()) {
