  salt.set(SERVICE_SALT)
  salt.set(usernameBuf, SERVICE_SALT.length)

  const hash = await argon2id({
    password,
    salt,
    parallelism: 1,
    iterations: 3,
    memorySize: 65536, // 64 MiB in KiB
    hashLength: 32,
    outputType: 'binary',
  })

  return hash
}

